SELECT rrt.refund_rate_table_id,
       rrt.policy_version_id,
       pv.version_no,
       rrt.standard_deduction_80_yn,
       rrt.effective_from
  FROM fgc.refund_rate_table rrt
  JOIN fgc.policy_version pv ON pv.policy_version_id = rrt.policy_version_id
 WHERE pv.status = 'ACTIVE'
   AND rrt.insurer_id = #{insurerId}
   AND rrt.product_id = #{productId}
   AND rrt.payment_term_months = #{paymentTermMonths}
   AND rrt.channel_code = #{channelCode}
   AND rrt.effective_from <= #{asOfDate}
   AND (rrt.effective_to IS NULL OR rrt.effective_to >= #{asOfDate})
 ORDER BY rrt.effective_from DESC
 LIMIT 1

SELECT refund_rate_pct
  FROM fgc.refund_rate_line
 WHERE refund_rate_table_id = #{refundRateTableId}
   AND contract_month_no = #{contractMonthNo}
